pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 unlock1, uint256 unlock2) public {
        // restrict to admissible amounts (avoid overflow)
        deposit1 = bound(deposit1, 1, type(uint120).max);
        deposit2 = bound(deposit2, 1, type(uint120).max);
        // use a fresh address as the depositor
