contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 firstAmount, uint256 secondAmount) public {
        // Keep amounts within admissible domain (non-zero and > 0 to have meaningful deposits)
        vm.assume(firstAmount > 0 && secondAmount > 0);
        // Use an arbitrary actor
        address actor = address(0x1234);
        vm.deal(actor, firstAmount + secondAmount);

        // First Put
        vm.prank(actor);
        c.Put{value: firstAmount}(0);

        // Second Put
        vm.prank(actor);
        c.Put{value: secondAmount}(0);

        // After two calls, the balance must be at least the larger of the two amounts
        // For the reference, balance = firstAmount + secondAmount >= max(firstAmount, secondAmount) always true
