import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to stay within reasonable gas limits but allow very large values near max uint256
        amount = bound(amount, 1, type(uint256).max);
        vm.deal(address(this), amount);
        // Call Put with arbitrary unlockTime; overflow is independent of time
        try c.Put{value: amount}(0) { } catch { }
        // The invariant: the contract's balance must equal the sum of all holders' balances.
        // In the buggy version, an overflow in acc.balance can cause the contract's balance to be less
        // than the recorded holder balance, violating the invariant that total deposited == contract balance.
        // Since we cannot iterate the mapping, we observe a consequence: if an overflow occurred,
        // the holder's recorded balance is less than amount (which equals msg.value).
        // The reference always records the full amount (no overflow check needed because it reverts on overflow).
        // The general rule: After a single deposit, the holder's balance plus the fallback value (0) must be at least the sent amount.
        (uint256 unlockTime, uint256 balance) = c.Acc(address(this));
        assertTrue(balance >= amount);
    }
}

