pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _seed, uint256 _am, uint8 _pad) public {
        // 1. Restrict to admissible domain: avoid revert on overflow in Put, and sensible collect amounts.
        // _seed generates the unlock time and fund amount.
        uint256 unlockTime = uint256(keccak256(abi.encode(_seed))) % 100_000;
        uint256 fundAmount = uint256(keccak256(abi.encode(_pad, _seed))) % 1000 ether + 2 ether; // at least MinSum+something
        _am = _am % 100 ether + 1; // 1 wei to 100 ether, avoid zero just to ensure call doesn't revert due to zero transfer

        // 2. Set up addresses. Use a helper to receive ETH so we can observe ETH balance of c.
        address actor = address(uint160(uint256(keccak256(abi.encode(_seed, _pad))) % (2**160 - 1)));
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));

        // Ensure actor has enough ETH to fund and pay gas.
        vm.deal(actor, fundAmount + 1 ether);

        // 3. Set unlock time and fund the contract.
        vm.warp(1);
        vm.prank(actor);
        c.Put{value: fundAmount}(unlockTime);

        // Ensure conditions for Collect are met.
        uint256 actorBalance = c.Acc(actor);
        vm.warp(unlockTime + 1); // pass unlock time

        // 4. Record pre-state
        uint256 preContractBalance = address(c).balance;

        // 5. Perform Collect
        vm.prank(actor);
        // Use a helper receiver to avoid having the actor's EOA receive ETH (which would complicate delta calc)
        // Instead, we just observe the contract balance delta.
        bool success;
        try c.Collect(_am) { success = true; } catch { success = false; }

        // 6. Post-state
        uint256 postContractBalance = address(c).balance;

        // 7. Assert: if Collect succeeded, the contract's ETH balance decreased by exactly _am.
        // The buggy version multiplies acc.balance by _am instead of subtracting, so the ETH transferred is still _am,
        // but balance becomes acc.balance * _am, causing mismatch between transferred amount and balance mutation.
        // The reference always satisfies: (pre - post) == _am on success.
        // On failure (e.g. MinSum condition not met due to mutated balance), the assertion holds vacuously by skipping.
        if (success) {
            assertTrue(preContractBalance - postContractBalance == _am);
        }
    }
}

