pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 unlockDelay) public {
        // Bound amounts to admissible range: deposit at least MinSum, collect non-zero
        depositAmount = bound(depositAmount, c.MinSum(), type(uint128).max);
        collectAmount = bound(collectAmount, 1, depositAmount);
        unlockDelay = bound(unlockDelay, 1, 365 days);

        // Deploy a helper to receive the collected Ether
        CollectorHelper helper = new CollectorHelper();
        address actor = address(helper);

        // Fund the actor, deposit into c
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(block.timestamp + unlockDelay);

        // Warp past unlock time
        vm.warp(block.timestamp + unlockDelay + 1);

        // Record pre-collect balance
        (, uint256 preBalance) = c.Acc(actor);

        // Collect
        vm.prank(actor);
        c.Collect(collectAmount);

        // Observe post-collect balance
        (, uint256 postBalance) = c.Acc(actor);

        // General rule: postBalance == preBalance - collectAmount
        assertTrue(postBalance == preBalance - collectAmount);
    }
}

contract CollectorHelper {
    function collect(address target, uint256 amount) external {
        C(target).Collect(amount);
    }
}

