pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 putAmount, uint256 unlockTimeDelta, uint256 collectAmount) public {
        // Bound to avoid overflow errors in Put (balance += msg.value requires overflow check)
        bound(putAmount, 0, type(uint120).max);
        bound(collectAmount, 0, type(uint120).max);
        // Ensure unlock time is in the past after warping, and reasonable
        vm.assume(unlockTimeDelta <= type(uint120).max);
        uint256 warpStart = block.timestamp;
        vm.assume(warpStart + unlockTimeDelta >= warpStart);

        address user = address(0x1234);
        vm.deal(user, putAmount);

        // Put funds with a future unlock time
        vm.prank(user);
        c.Put{value: putAmount}(warpStart + unlockTimeDelta);

        uint256 invariantBefore = address(c).balance + c.Acc(user).balance;

        // Warp past the unlock time
        vm.warp(warpStart + unlockTimeDelta + 1);
        vm.roll(block.number + 1);

        // Collect must be possible: balance >= MinSum (1 ether), balance >= collectAmount, and warped past unlock
        vm.assume(putAmount >= 1 ether);
        vm.assume(putAmount >= collectAmount);

        vm.deal(user, 0);
        vm.prank(user);
        try c.Collect(collectAmount) {
            // success: invariant must hold
            uint256 invariantAfter = address(c).balance + c.Acc(user).balance;
            assertTrue(invariantAfter == invariantBefore);
        } catch {
            // Collect reverted: no state change, so invariant trivially holds (not asserted here)
        }
    }
}

